import{B,C,read,circle}from'../ten-utils.js';import{fmt10}from'../ten-math.js';
export default({g,p,extra,t})=>{let m=extra.mode??0;if(m===0){let ph=p[0],color=ph<7?C.pink:ph===7?C.green:C.blue;g.box(0,0,0,.85,.7,.45);for(let i=0;i<20;i++)g.sphere(Math.sin(i*4+t*.3)*.7,Math.cos(i*5+t*.2)*.5,Math.sin(i)*.3,.055,color);g.text(0,-1.05,0,B(`pH = ${ph}`,`pH = ${ph}`));return[read('Nature','प्रकृति',ph<7?B('Acidic','अम्लीय'):ph===7?B('Neutral','उदासीन'):B('Basic','क्षारकीय')),read('H+ concentration','H+ सांद्रता',`10^(-${ph})`,'mol/L')]}
 if(m===1){let base=p[0],acid=10;g.box(0,.1,0,.8,.65,.4);let excess=Math.abs(base-acid);for(let i=0;i<10;i++)g.sphere(Math.sin(i*2)*.65,.1+Math.cos(i*3)*.45,0,.045,C.green);for(let i=0;i<excess;i++)g.sphere(-.6+i*.12,.25*Math.sin(i+t),0,.065,base<10?C.pink:C.blue);g.text(0,-1,0,B('H+ + OH− → H2O','H+ + OH− → H2O'));return[read('Acid volume','अम्ल का आयतन',10,'mL'),read('Base added','मिलाया क्षारक',base,'mL'),read('Equal-concentration strong acid/base model','समान सांद्रता प्रबल अम्ल-क्षारक मॉडल',base===10?B('Equivalent; neutral at 25°C','समतुल्य; 25°C पर उदासीन'):base<10?B('Acid in excess','अम्ल अधिक'):B('Base in excess','क्षारक अधिक'))]}
 let hydrated=p[0];for(let i=0;i<10;i++){let x=(i%5-2)*.4,y=Math.floor(i/5)*.5-.25;g.sphere(x,y,0,.13,i<hydrated?C.blue:C.white);if(i<hydrated)for(let j=0;j<5;j++){let a=j*Math.PI*2/5;g.sphere(x+.2*Math.cos(a),y+.2*Math.sin(a),.1,.025,C.gold)}}g.text(0,-1,0,B('CuSO4·5H2O: blue hydrated crystals','CuSO4·5H2O: नीले जलयोजित क्रिस्टल'));return[read('Hydrated model units','जलयोजित मॉडल इकाइयाँ',hydrated,'/ 10'),read('Water per hydrated formula unit','हर जलयोजित सूत्र इकाई में जल',5,'H2O'),read('Anhydrous CuSO4','निर्जल CuSO4',B('White','सफेद'))]};
